import{_ as t,h as n,i as a,c as i,v as o,p as d,x as r,m as c,e as P,S as E}from"./chunks/framework.Dvtg8yj2.js";const N=JSON.parse('{"title":"异构集群调度","description":"","frontmatter":{"title":"异构集群调度","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/hetero-cluster.md","filePath":"llm/hetero-cluster.md","lastUpdated":1788454257000}'),C={name:"llm/hetero-cluster.md"};function s(U,e,B,A,p,h){const l=n("Mermaid");return a(),i("div",null,[e[1]||(e[1]=o('<h1 id="异构集群调度" tabindex="-1">异构集群调度 <a class="header-anchor" href="#异构集群调度" aria-label="Permalink to &quot;异构集群调度&quot;">​</a></h1><div class="epigraph"><p>调度器看见的若只是「加速器张数」，就会把张量并行组拆到两种不会集合通信的芯片上；异构首先是拓扑与运行时，其次才是装箱。</p><footer>—— 对照华为云 CCE 对 GPU / NPU 分插件接入与 Volcano 拓扑感知调度的公开说明</footer></div><p>智算集群里同时出现 NVIDIA GPU、昇腾 NPU、鲲鹏 CPU 已经是常态：有的机房按供应混装，有的在 <a href="/llm/cloudmatrix-384">CloudMatrix 384</a> 超节点内部就把 NPU 与 CPU 池化。Kubernetes 默认只懂 CPU / 内存；加速器靠 Device Plugin 上报。华为云 CCE 把这件事拆成两套 AI 套件——NVIDIA GPU 一套、Ascend NPU 一套——再用 Volcano 做队列、优先级和拓扑感知。本篇写<strong>异构调度要守的边界</strong>，不发明未公开的装箱启发式，也不把某一云厂商控制台的默认策略写成标准。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同构 GPU 集群的口诀是：一个 TP 组绑在同一 NVLink 域，副本用数据并行散开。换成异构之后，口诀失效的方式有三种。<strong>设备指令集不同</strong>：CUDA 核不能在 NPU 上跑，CANN 图不能在 GPU 上跑，混进同一进程的「一半 worker」没有集合通信可做。<strong>互连不同</strong>：GPU 侧 NCCL 走 NVLink / IB，昇腾侧 HCCL 走 HCCS / UB / RoCE，跨厂商没有一种可把 All-Reduce 接到一起的公开库。<strong>资源语义不同</strong>：GPU 可 MIG 或按卡共享；NPU 有芯级独占、虚拟化 vNPU、以及超节点内按 UB 域切的逻辑加速器。调度器若只用 <code>nvidia.com/gpu: 8</code> 与 <code>huawei.com/ascend-*</code> 的整数相加来凑「16 卡」，会得到无法启动的 Pod。</p><p>第二层问题是代数混部。昇腾 910B 与 910C 的自定义算子按 <code>SOC_VERSION</code> 分支编译，<a href="/llm/vllm-ascend">vLLM-Ascend</a> 的核不是一份二进制打天下。把 910B 与 910C 塞进同一 TP 组，即使 HCCL 能建链，核形状与 UB / HCCS 带宽也不在同一档。异构包括「两代昇腾」，不只是「GPU 对 NPU」。</p><h3 id="上报与可调度资源必须分开命名" tabindex="-1">上报与可调度资源必须分开命名 <a class="header-anchor" href="#上报与可调度资源必须分开命名" aria-label="Permalink to &quot;上报与可调度资源必须分开命名&quot;">​</a></h3><p>CCE 文档把 GPU 与 NPU 写成不同插件、不同资源名。NPU 独占调度按张申请；拓扑感知调度还要看板内互连，减少碎片和拥塞；虚拟化则把一张物理 NPU 切成若干 vNPU，资源名带算力与内存规格。GPU 侧同样有整卡、共享、虚拟化三条。调度器的第一步不是打分，是<strong>拒绝跨资源名的凑数</strong>。用户清单里应写「本作业的加速器类型」，而不是「任意 8 张加速器」。</p><p><span class="marginnote">Volcano 在 CCE 里与 CloudMatrix 网络拓扑感知做过集成，这是产品文档中的能力描述。具体打分权重、超节点内是否允许跨柜 TP，以你集群里安装的调度器版本为准，不要把邻区 GPU 的 GPU-Affinity 插件配置抄到昇腾节点上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把异构集群画成若干<strong>同构池</strong>，池之间只做请求级路由，不做层内集合通信。池的键至少包括：厂商（NVIDIA / 昇腾）、代数（A100 / H100 / 910B / 910C）、互连域（NVLink 机柜 / UB 超节点 / 普通 PCIe 盒）、运行时（vLLM-CUDA / vLLM-Ascend / MindIE）。作业在提交时选定一个池；调度器在池内做拓扑感知装箱：TP 组落在同一互连域，副本可跨域。</p><p>节点标签与污点是落地手段。GPU 节点与 NPU 节点用 <code>device-vendor</code>、<code>npu-arch</code>、<code>nvlink-domain</code> / <code>ub-domain</code> 区分；Device Plugin 只在本类节点上报本类资源。Kube-scheduler 或 Volcano 的 predicate 必须检查：Pod 请求的资源名在节点上存在，且节点标签与作业的亲和一致。CloudMatrix 上还要把「本超节点 UB 域」当成可分配对象，避免把 8 路 TP 拆到两个超节点再走 RoCE——那是把 Scale-Up 作业降成 Scale-Out。</p><p>在线推理与离线训练混部时，用队列和优先级，而不是用「NPU 上再叠一个 GPU 作业」。CCE 的云原生混部谈的是 CPU 超卖与在离线；加速器混部若没有虚拟化切分，不要假设一张 910C 能安全地跑两个不同框架的 worker。</p>',13)),(a(),d(E,null,{default:r(()=>[P(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20JOB%5B%22%E8%AE%AD%E7%BB%83%20%2F%20%E6%8E%A8%E7%90%86%E4%BD%9C%E4%B8%9A%22%5D%20--%3E%20SEL%5B%22%E9%80%89%E5%AE%9A%E5%90%8C%E6%9E%84%E6%B1%A0%EF%BC%9A%E5%8E%82%E5%95%86%20%C3%97%20%E4%BB%A3%E6%95%B0%20%C3%97%20%E4%BA%92%E8%BF%9E%E5%9F%9F%20%C3%97%20%E8%BF%90%E8%A1%8C%E6%97%B6%22%5D%0A%20%20SEL%20--%3E%20GPU%5B%22GPU%20%E6%B1%A0%EF%BC%9ANCCL%20%2B%20CUDA%20%E6%8F%92%E4%BB%B6%22%5D%0A%20%20SEL%20--%3E%20NPU%5B%22NPU%20%E6%B1%A0%EF%BC%9AHCCL%20%2B%20%E6%98%87%E8%85%BE%E6%8F%92%E4%BB%B6%22%5D%0A%20%20SEL%20--%3E%20CM%5B%22%E8%B6%85%E8%8A%82%E7%82%B9%E6%B1%A0%EF%BC%9AUB%20%E5%9F%9F%E5%86%85%E6%A8%A1%E5%9E%8B%E5%B9%B6%E8%A1%8C%22%5D%0A%20%20GPU%20--%3E%20TP1%5B%22TP%20%E5%8F%AA%E5%9C%A8%20NVLink%20%E5%9F%9F%22%5D%0A%20%20NPU%20--%3E%20TP2%5B%22TP%20%E5%8F%AA%E5%9C%A8%20HCCS%20%2F%20UB%20%E5%9F%9F%22%5D%0A%20%20CM%20--%3E%20TP3%5B%22TP%20%2F%20EP%20%E4%BC%98%E5%85%88%E6%95%B4%E8%B6%85%E8%8A%82%E7%82%B9%22%5D%0A%20%20GPU%20--%3E%7C%22%E8%AF%B7%E6%B1%82%E7%BA%A7%22%7C%20GW%5B%22%E7%BD%91%E5%85%B3%20%2F%20%E9%98%9F%E5%88%97%22%5D%0A%20%20NPU%20--%3E%20GW%0A%20%20CM%20--%3E%20GW%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h3 id="请求级异构与层内异构" tabindex="-1">请求级异构与层内异构 <a class="header-anchor" href="#请求级异构与层内异构" aria-label="Permalink to &quot;请求级异构与层内异构&quot;">​</a></h3><p>请求级异构是合法的：同一个 OpenAI 网关后面，A 模型在 GPU 副本，B 模型在昇腾副本，按 <code>model</code> 字段分流，见 <a href="/llm/kv-aware-routing">KV 感知路由</a> 的「先认模型再认缓存」。层内异构不合法：同一层的 TP All-Reduce 不能一半 NCCL、一半 HCCL。专家并行若跨出 UB 域，通信语义变成 RDMA 平面，延迟档位变了，那是 Scale-Out，要按跨超节点来规划，而不是当「调度器聪明地借了几张别的卡」。</p><p>CPU 与 NPU 的异构是另一条轴。CloudMatrix 把鲲鹏与 910C 都挂在 UB 上，论文里写明可按负载组合内存型缓存节点与计算型 NPU。调度的是<strong>池化后的角色</strong>（prefill 池、decode 池、KV 内存池），不是把 CPU 核当成一张假 GPU 写进 <code>nvidia.com/gpu</code>。擎天 DPU 上的 MatrixResource / MatrixLink 代理负责超节点内的实例与链路，这层在普通 CCE 节点上并不存在。</p><p><span class="marginnote">资源名 <code>huawei.com/ascend-310</code> 与 <code>huawei.com/ascend-1980</code> 出现在企业文档里，对应不同昇腾产品。抄错资源名时，事件是 <code>Insufficient huawei.com/...</code>，看起来像容量不足，其实是节点根本没有这种设备。先对插件与资源名，再扩容。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Device Plugin 通过 kubelet 注册扩展资源，scheduler 只看见整数配额。拓扑感知要额外的设备拓扑（哪几张卡在同一 HCCS / UB 平面）。没有这张图，Volcano 也只能做「节点上 NPU 数量够不够」，把同节点但跨平面的卡绑进一组，HCCL 性能会掉到你以为的域内带宽以下。超节点场景下，爆炸半径是整域：通信柜或 UB 平面故障应把该超节点从池里摘掉，而不是继续往半通域里塞 TP。</p><p>异构还改变故障与滚动。GPU 镜像含 CUDA 驱动用户态，NPU 镜像含 CANN；滚动升级不能用同一 DaemonSet 往两类节点推驱动。探针必须分运行时：vLLM 的 <code>/health</code> 与 MindIE 的探针不是同一个语义。取消与 KV 释放仍按各引擎自己的规则，见 <a href="/llm/sse-cancel">sse-cancel</a>，调度器不负责把 GPU 页表翻译成 NPU 块表。</p><h3 id="利用率不是把卡填满" tabindex="-1">利用率不是把卡填满 <a class="header-anchor" href="#利用率不是把卡填满" aria-label="Permalink to &quot;利用率不是把卡填满&quot;">​</a></h3><p>混部的诱惑是把空闲 NPU 借给 GPU 作业的溢出队列。若运行时不能在该卡上执行，填满只是制造 Pending。即便虚拟化切了 vNPU，共享的是同一 Cube 与 HBM，延迟 SLA 会互相踩。异构调度的一阶目标是<strong>正确性与通信域</strong>，二阶才是利用率。利用率用同构池内的连续批、分时队列、虚拟化来做，不要用跨厂商拼卡。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要在没有共同集合通信库的前提下做跨厂商 TP / EP。不要把 CloudMatrix 超节点当 48 台互不往来的 8 卡机来调度——那是买了 UB 却只用以太网编程模型，与 <a href="/llm/rack-as-accelerator">机柜作为一块逻辑加速器</a> 的教训相同。不要假设 CCE 的 GPU 虚拟化参数能套到 vNPU。不要编造未公开的超节点内端口级调度算法。</p><p>成本账：异构池增加了镜像、驱动、监控和值班手册的份数；收益是供应可替代、以及超节点内 CPU 内存池给 KV 用。若集群很小、只有一种加速器，不要为「异构」上两套插件。</p><p><span class="marginnote">出处：华为云 CCE《调度概述》与 AI 套件（NVIDIA GPU / Ascend NPU）说明、Volcano 在 CCE 上的队列与拓扑感知描述，以及 CloudMatrix384 论文中 CPU/NPU 池化与三平面网络。不引用未公开的调度器源码阈值。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>异构调度先按厂商、代数、互连域、运行时分同构池，池内做 TP，池间只做请求级分流。</li><li>GPU 与 NPU 用不同 Device Plugin 和资源名；跨资源名凑卡会得到无法通信的进程组。</li><li>两代昇腾也是异构；插件核与带宽不共享同一假设。</li><li>CloudMatrix 上的异构还包括 UB 上的 CPU 内存池与 NPU 计算池，按角色调度而不是按「假 GPU」。</li><li>利用率在同构池内做；跨厂商填卡不是调度，是配置错误。</li><li>出处：华为云 CCE 调度与 AI 套件文档；CloudMatrix384 公开论文中的资源池化。</li></ul>',15))])}const m=t(C,[["render",s]]);export{N as __pageData,m as default};
